package cn.binbin.crm;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.validation.constraints.*;
import java.time.*;
import java.util.*;
import java.util.function.Function;
import java.util.function.Supplier;
import org.springframework.jdbc.core.namedparam.NamedParameterJdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class SalesService {
    public static final List<String> STAGES=List.of("CONTACT","NEEDS","SOLUTION","NEGOTIATION","READY","WON","LOST");
    public record OpportunityCreate(@NotNull UUID customerId,UUID sourceLeadId,@NotBlank @Size(max=200) String title,@NotNull UUID ownerMemberId,
        @NotNull @Min(0) @Max(100000000000L) Long amountCents,@NotNull LocalDate closeDate,@NotBlank @Size(max=1000) String nextAction,@Size(max=4000) String description) {}
    public record OpportunityEdit(@NotNull @Min(0) Long expectedVersion,@NotBlank @Size(max=200) String title,@NotNull UUID ownerMemberId,
        @NotNull @Min(0) @Max(100000000000L) Long amountCents,@NotNull LocalDate closeDate,@NotBlank @Size(max=1000) String nextAction,@Size(max=4000) String description) {}
    public record StageInput(@NotNull @Min(0) Long expectedVersion,@NotNull @Pattern(regexp="CONTACT|NEEDS|SOLUTION|NEGOTIATION|READY|WON|LOST") String stage,
        @NotBlank @Size(max=1000) String reason,@Size(max=1000) String nextAction,@Min(1) @Max(100000000000L) Long actualAmountCents) {}
    public record TaskCreate(UUID customerId,UUID opportunityId,@NotBlank @Size(max=200) String title,@Size(max=4000) String description,
        @NotNull UUID assigneeMemberId,@NotNull LocalDate dueDate,@NotNull @Pattern(regexp="LOW|NORMAL|HIGH") String priority) {}
    public record TaskEdit(@NotNull @Min(0) Long expectedVersion,@NotBlank @Size(max=200) String title,@Size(max=4000) String description,
        @NotNull UUID assigneeMemberId,@NotNull LocalDate dueDate,@NotNull @Pattern(regexp="LOW|NORMAL|HIGH") String priority) {}
    public record VersionInput(@NotNull @Min(0) Long expectedVersion) {}
    public record ActivityCreate(@NotNull UUID customerId,UUID opportunityId,@NotNull @Pattern(regexp="CALL|VISIT|MEETING|EMAIL|OTHER") String activityType,
        @NotBlank @Size(max=4000) String content,@NotNull Instant occurredAt) {}
    private record TargetRequest(UUID id,Object input) {}
    private final NamedParameterJdbcTemplate db;private final TransactionTemplate tx;private final AuthService auth;
    private final CustomerService customers;private final BusinessService business;private final ObjectMapper json;
    public SalesService(NamedParameterJdbcTemplate db,TransactionTemplate tx,AuthService auth,CustomerService customers,BusinessService business,ObjectMapper json){this.db=db;this.tx=tx;this.auth=auth;this.customers=customers;this.business=business;this.json=json;}
    private static String text(String v){return v==null?"":v.strip();}
    private static boolean closed(String stage){return Set.of("WON","LOST").contains(stage);}
    private <T> T scoped(AuthService.Session s,String module,boolean write,Function<AuthService.Actor,T> fn){return tx.execute(status->{
        if(write&&s.tenantId()!=null)db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",Map.of("tenant",s.tenantId()),UUID.class);
        var a=auth.actor(s);if(a.supportGrantId()!=null)throw ApiError.forbidden("当前支持授权不包含商机、跟进和待办");
        var b=a.businessAccess();boolean read=true,canWrite=false;
        switch(module){case "opportunity"-> {read=b.opportunities().read()&&a.canReadCustomers();canWrite=b.opportunities().write()&&a.canWriteCustomers();}
            case "task"->{read=b.tasks().read();canWrite=b.tasks().write();}case "activity"->{read=b.activityRead();canWrite=b.activityWrite();}default-> {}}
        if(!read||write&&!canWrite)throw ApiError.forbidden("当前角色没有该模块权限");
        if(write&&!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅已到期，当前仅允许查看");
        db.queryForObject("SELECT set_config('crm.tenant_id',:tenant,true)",Map.of("tenant",a.tenant().id().toString()),String.class);return fn.apply(a);
    });}
    Map<String,Object> params(AuthService.Actor a){
        var p=customers.scope(a);var b=a.businessAccess();putScope(p,"op",b.opportunities());putScope(p,"task",b.tasks());putScope(p,"lead",b.leads());
        p.put("customerReader",a.canReadCustomers());p.put("opReader",b.opportunities().read());
        p.put("opWriter",b.opportunities().write()&&a.tenant().subscriptionEnd().isAfter(Instant.now()));p.put("taskWriter",b.tasks().write()&&a.tenant().subscriptionEnd().isAfter(Instant.now()));p.put("leadReader",b.leads().read());return p;
    }
    private static void putScope(Map<String,Object> p,String name,BusinessAccess.Scope s){p.put(name+"ReadAll",s.readAll());p.put(name+"ReadDepartment",s.readDepartment());p.put(name+"WriteAll",s.writeAll());p.put(name+"WriteDepartment",s.writeDepartment());}
    private static String own(String alias,String owner,String prefix,boolean write){return "(:"+prefix+(write?"WriteAll":"ReadAll")+" OR "+alias+"."+owner+"=:member OR (:"+prefix+(write?"WriteDepartment":"ReadDepartment")+" AND EXISTS(SELECT 1 FROM sys_tenant_member sm WHERE sm.tenant_id="+alias+".tenant_id AND sm.id="+alias+"."+owner+" AND sm.department_id=:department)))";}
    static final String OP_READ="o.tenant_id=:tenant AND :opReader AND :customerReader AND "+CustomerService.READ+" AND "+own("o","owner_member_id","op",false);
    static final String OP_WRITE="(:opWriter AND "+CustomerService.WRITE+" AND "+own("o","owner_member_id","op",true)+")";
    static final String OP_FROM=" FROM crm_opportunity o JOIN crm_customer c ON c.tenant_id=o.tenant_id AND c.id=o.customer_id JOIN sys_tenant_member om ON om.tenant_id=o.tenant_id AND om.id=o.owner_member_id LEFT JOIN crm_lead l ON l.tenant_id=o.tenant_id AND l.id=o.source_lead_id ";
    private static final String OP_SELECT="SELECT o.id,o.customer_id,c.customer_name,o.title,o.owner_member_id,om.display_name AS owner_name,o.stage,o.amount_cents,o.actual_amount_cents,o.close_date,o.next_action,o.description,o.closed_at,o.version,o.updated_at,(o.stage NOT IN ('WON','LOST') AND "+OP_WRITE+") AS can_write,("+OP_WRITE+") AS can_link,CASE WHEN :leadReader AND "+own("l","owner_member_id","lead",false)+" THEN l.id END AS source_lead_id,CASE WHEN :leadReader AND "+own("l","owner_member_id","lead",false)+" THEN l.company_name END AS source_lead_name"+OP_FROM;
    private List<Map<String,Object>> rows(String sql,Map<String,?> p){return db.queryForList(sql,p).stream().map(SaasService::view).toList();}
    private Map<String,Object> one(String sql,Map<String,?> p){var rows=rows(sql,p);if(rows.isEmpty())throw ApiError.missing();return rows.getFirst();}
    Map<String,Object> opportunity(AuthService.Actor a,UUID id){var p=params(a);p.put("id",id);return one(OP_SELECT+"WHERE "+OP_READ+" AND o.id=:id",p);}
    private void opportunityWrite(AuthService.Actor a,UUID id,boolean allowClosed){var o=opportunity(a,id);if(!allowClosed&&closed((String)o.get("stage")))throw ApiError.conflict("已成交或丢单的商机保持只读");var p=params(a);p.put("id",id);if(db.queryForObject("SELECT count(*)"+OP_FROM+"WHERE "+OP_READ+" AND "+OP_WRITE+" AND o.id=:id",p,Integer.class)!=1)throw ApiError.forbidden("无权编辑该商机");}
    private static void page(int page,int size,String q){if(page<1||page>100000||size<1||size>100||q.length()>100)throw ApiError.bad("分页或搜索条件无效");}
    private static void date(LocalDate value){if(value==null||value.isBefore(LocalDate.of(2000,1,1))||value.isAfter(LocalDate.of(2100,12,31)))throw ApiError.bad("日期需在2000至2100年之间");}
    public Map<String,Object> opportunity(AuthService.Session s,UUID id){return scoped(s,"opportunity",false,a->opportunity(a,id));}
    private String opportunityWhere(){return OP_READ+" AND (:stage='' OR o.stage=:stage) AND (cast(:customer AS uuid) IS NULL OR o.customer_id=:customer) AND (:q='' OR strpos(lower(o.title),lower(:q))>0 OR strpos(lower(c.customer_name),lower(:q))>0)";}
    public BusinessService.Page<Map<String,Object>> opportunities(AuthService.Session s,int page,int size,String q,String stage,UUID customer){page(page,size,q);if(!stage.isEmpty()&&!STAGES.contains(stage))throw ApiError.bad("商机阶段无效");return scoped(s,"opportunity",false,a->{var p=params(a);p.put("stage",stage);p.put("customer",customer);p.put("q",text(q));p.put("limit",size);p.put("offset",((long)page-1)*size);if(customer!=null)customers.get(a,customer);long total=db.queryForObject("SELECT count(*)"+OP_FROM+"WHERE "+opportunityWhere(),p,Long.class);return new BusinessService.Page<>(rows(OP_SELECT+"WHERE "+opportunityWhere()+" ORDER BY o.updated_at DESC,o.id LIMIT :limit OFFSET :offset",p),page,size,total);});}
    public List<Map<String,Object>> board(AuthService.Session s,String q,UUID customer){page(1,12,q);return scoped(s,"opportunity",false,a->{if(customer!=null)customers.get(a,customer);var p=params(a);p.put("customer",customer);p.put("q",text(q));var result=new ArrayList<Map<String,Object>>();for(String stage:STAGES){p.put("stage",stage);var entry=new LinkedHashMap<String,Object>(one("SELECT count(*) AS total,coalesce(sum(o.amount_cents),0) AS amount_cents,coalesce(sum(o.actual_amount_cents),0) AS actual_amount_cents"+OP_FROM+"WHERE "+opportunityWhere(),p));entry.put("stage",stage);entry.put("items",rows(OP_SELECT+"WHERE "+opportunityWhere()+" ORDER BY o.updated_at DESC,o.id LIMIT 12",p));result.add(entry);}return result;});}
    public List<Map<String,Object>> owners(AuthService.Session s,String module){if(!Set.of("opportunity","task").contains(module))throw ApiError.bad("负责人模块无效");return scoped(s,module,false,a->{var p=params(a);String prefix=module.equals("task")?"task":"op";return rows("SELECT m.id,m.display_name AS name FROM sys_tenant_member m JOIN iam_user u ON u.id=m.user_id WHERE m.tenant_id=:tenant AND m.status='ACTIVE' AND u.status='ACTIVE' AND "+own("m","id",prefix,true)+" AND EXISTS(SELECT 1 FROM sys_member_role r JOIN sys_role_policy rp ON rp.tenant_id=r.tenant_id AND rp.role_code=r.role_code WHERE r.tenant_id=m.tenant_id AND r.member_id=m.id AND rp."+module+"_can_write) ORDER BY m.display_name,m.id",p);});}
    private void owner(AuthService.Actor a,String module,UUID id){if(owners(a.session(),module).stream().noneMatch(m->id.equals(m.get("id"))))throw ApiError.bad("负责人无效或超出模块权限");}
    private void customerWrite(AuthService.Actor a,UUID id){if(!customers.get(a,id).canWrite())throw ApiError.forbidden("无权编辑关联客户");}
    private void recipient(AuthService.Actor a,UUID member,UUID customer,UUID opportunity){
        if(customer==null)return;
        var row=db.queryForMap("SELECT display_name,department_id FROM sys_tenant_member WHERE tenant_id=:tenant AND id=:member",Map.of("tenant",a.tenant().id(),"member",member));
        var policies=db.queryForList("SELECT p.* FROM sys_role_policy p JOIN sys_member_role r ON r.tenant_id=p.tenant_id AND r.role_code=p.role_code WHERE r.tenant_id=:tenant AND r.member_id=:member",Map.of("tenant",a.tenant().id(),"member",member));
        var t=a.tenant();var target=new AuthService.Tenant(t.id(),t.code(),t.name(),t.status(),t.subscriptionEnd(),member,(String)row.get("display_name"),Set.of());
        var access=CustomerAccess.from(policies);var assigned=new AuthService.Actor(a.session(),target,access,(UUID)row.get("department_id"),null,BusinessAccess.from(policies,access));
        try{if(!assigned.canReadCustomers())throw ApiError.missing();customers.get(assigned,customer);if(opportunity!=null)opportunity(assigned,opportunity);}
        catch(ApiError missing){throw ApiError.bad("负责人尚无关联客户或商机的读取权限，请先调整协作范围");}
    }
    private Map<String,Object> opportunityParams(AuthService.Actor a,UUID id,String title,UUID owner,Long amount,LocalDate closeDate,String next,String description){date(closeDate);owner(a,"opportunity",owner);var p=params(a);p.put("id",id);p.put("title",text(title));p.put("owner",owner);p.put("amount",amount);p.put("date",closeDate);p.put("next",text(next));p.put("description",text(description));return p;}
    public Map<String,Object> createOpportunity(AuthService.Session s,OpportunityCreate input,String key,UUID trace){return scoped(s,"opportunity",true,a->{UUID id=once(a,"opportunity.create",key,input,()->{
        customerWrite(a,input.customerId());if(input.sourceLeadId()!=null){var l=business.lead(s,input.sourceLeadId());if(!"CONVERTED".equals(l.status())||!input.customerId().equals(l.convertedCustomerId()))throw ApiError.bad("来源线索需已转换到该客户");}
        UUID created=UUID.randomUUID();var p=opportunityParams(a,created,input.title(),input.ownerMemberId(),input.amountCents(),input.closeDate(),input.nextAction(),input.description());recipient(a,input.ownerMemberId(),input.customerId(),null);p.put("customer",input.customerId());p.put("lead",input.sourceLeadId());
        db.update("INSERT INTO crm_opportunity(id,tenant_id,customer_id,source_lead_id,title,owner_member_id,amount_cents,close_date,next_action,description) VALUES(:id,:tenant,:customer,:lead,:title,:owner,:amount,:date,:next,:description)",p);
        history(a,created,null,"CONTACT","创建商机",text(input.nextAction()),input.amountCents(),null,0);audit(a,"OPPORTUNITY_CREATED","OPPORTUNITY",created,0,trace);return created;
    });return opportunity(a,id);});}
    public Map<String,Object> editOpportunity(AuthService.Session s,UUID id,OpportunityEdit input,UUID trace){return scoped(s,"opportunity",true,a->{opportunityWrite(a,id,false);var current=opportunity(a,id);recipient(a,input.ownerMemberId(),(UUID)current.get("customerId"),null);var p=opportunityParams(a,id,input.title(),input.ownerMemberId(),input.amountCents(),input.closeDate(),input.nextAction(),input.description());p.put("version",input.expectedVersion());int changed=db.update("UPDATE crm_opportunity SET title=:title,owner_member_id=:owner,amount_cents=:amount,close_date=:date,next_action=:next,description=:description,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND stage NOT IN ('WON','LOST')",p);if(changed!=1)throw ApiError.conflict("商机已变化，请刷新后保存");audit(a,"OPPORTUNITY_UPDATED","OPPORTUNITY",id,input.expectedVersion()+1,trace);return opportunity(a,id);});}
    public static void transition(String from,StageInput input){
        int f=STAGES.indexOf(from),t=STAGES.indexOf(input.stage());if(f<0||t<0||closed(from)||from.equals(input.stage())||!(input.stage().equals("LOST")||input.stage().equals("WON")&&from.equals("READY")||t<5&&Math.abs(f-t)==1))throw ApiError.bad("阶段需逐步推进或回退，签约准备后才能成交；关闭后不能重开");
        if(text(input.reason()).isEmpty())throw ApiError.bad("请填写阶段变更原因");
        if(input.stage().equals("WON")){if(input.actualAmountCents()==null||input.actualAmountCents()<1||input.actualAmountCents()>100000000000L)throw ApiError.bad("成交需填写有效的实际成交金额");}
        else if(input.actualAmountCents()!=null)throw ApiError.bad("只有成交阶段可填写实际成交金额");
        if(!closed(input.stage())&&text(input.nextAction()).isEmpty())throw ApiError.bad("未结束的商机需填写下一步");
    }
    public Map<String,Object> stage(AuthService.Session s,UUID id,StageInput input,String key,UUID trace){return scoped(s,"opportunity",true,a->{UUID result=once(a,"opportunity.stage",key,new TargetRequest(id,input),()->{
        opportunityWrite(a,id,false);var current=opportunity(a,id);if(((Number)current.get("version")).longValue()!=input.expectedVersion())throw ApiError.conflict("商机已变化，请刷新后推进");transition((String)current.get("stage"),input);
        var p=params(a);p.put("id",id);p.put("version",input.expectedVersion());p.put("stage",input.stage());p.put("actual",input.actualAmountCents());p.put("next",closed(input.stage())?"":text(input.nextAction()));p.put("closed",closed(input.stage()));
        int changed=db.update("UPDATE crm_opportunity SET stage=:stage,actual_amount_cents=:actual,next_action=:next,closed_at=CASE WHEN :closed THEN now() ELSE NULL END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version",p);if(changed!=1)throw ApiError.conflict("商机已变化，请刷新后推进");
        history(a,id,(String)current.get("stage"),input.stage(),text(input.reason()),(String)p.get("next"),((Number)current.get("amountCents")).longValue(),input.actualAmountCents(),input.expectedVersion()+1);audit(a,"OPPORTUNITY_STAGE_CHANGED","OPPORTUNITY",id,input.expectedVersion()+1,trace);return id;
    });return opportunity(a,result);});}
    private void history(AuthService.Actor a,UUID id,String from,String to,String reason,String next,long amount,Long actual,long version){var p=params(a);p.put("id",UUID.randomUUID());p.put("opportunity",id);p.put("from",from);p.put("to",to);p.put("reason",reason);p.put("next",next);p.put("amount",amount);p.put("actual",actual);p.put("version",version);db.update("INSERT INTO crm_opportunity_history(id,tenant_id,opportunity_id,from_stage,to_stage,reason,next_action,amount_cents,actual_amount_cents,actor_member_id,business_version) VALUES(:id,:tenant,:opportunity,:from,:to,:reason,:next,:amount,:actual,:member,:version)",p);}
    public BusinessService.Page<Map<String,Object>> history(AuthService.Session s,UUID id,int page,int size){page(page,size,"");return scoped(s,"opportunity",false,a->{opportunity(a,id);var p=params(a);p.put("id",id);p.put("limit",size);p.put("offset",((long)page-1)*size);long count=db.queryForObject("SELECT count(*) FROM crm_opportunity_history WHERE tenant_id=:tenant AND opportunity_id=:id",p,Long.class);return new BusinessService.Page<>(rows("SELECT h.*,m.display_name AS actor_name FROM crm_opportunity_history h JOIN sys_tenant_member m ON m.tenant_id=h.tenant_id AND m.id=h.actor_member_id WHERE h.tenant_id=:tenant AND h.opportunity_id=:id ORDER BY h.business_version DESC,h.id LIMIT :limit OFFSET :offset",p),page,size,count);});}
    private static final String LINK_READ="(x.customer_id IS NULL OR (:customerReader AND "+CustomerService.READ+")) AND (x.opportunity_id IS NULL OR ("+OP_READ+"))";
    private static final String LINK_WRITE="(x.customer_id IS NULL OR "+CustomerService.WRITE+") AND (x.opportunity_id IS NULL OR "+OP_WRITE+")";
    static final String TASK_FROM=" FROM crm_task x JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.assignee_member_id LEFT JOIN crm_customer c ON c.tenant_id=x.tenant_id AND c.id=x.customer_id LEFT JOIN crm_opportunity o ON o.tenant_id=x.tenant_id AND o.id=x.opportunity_id ";
    static final String TASK_READ="x.tenant_id=:tenant AND "+own("x","assignee_member_id","task",false)+" AND "+LINK_READ;
    private static final String TASK_SELECT="SELECT x.*,c.customer_name,o.title AS opportunity_title,m.display_name AS assignee_name,(:taskWriter AND "+own("x","assignee_member_id","task",true)+" AND "+LINK_WRITE+") AS can_write,(x.status='PENDING' AND x.due_date<cast(:today AS date)) AS overdue"+TASK_FROM;
    Map<String,Object> task(AuthService.Actor a,UUID id){var p=params(a);p.put("id",id);p.put("today",LocalDate.now(ZoneId.of("Asia/Shanghai")));return one(TASK_SELECT+"WHERE "+TASK_READ+" AND x.id=:id",p);}
    public Map<String,Object> task(AuthService.Session s,UUID id){return scoped(s,"task",false,a->task(a,id));}
    public BusinessService.Page<Map<String,Object>> tasks(AuthService.Session s,int page,int size,String q,String state,boolean mine,UUID customer,UUID opportunity){page(page,size,q);if(!Set.of("","PENDING","DONE","OVERDUE").contains(state))throw ApiError.bad("待办状态无效");return scoped(s,"task",false,a->{validateFilters(s,a,customer,opportunity);var p=params(a);p.put("today",LocalDate.now(ZoneId.of("Asia/Shanghai")));p.put("state",state);p.put("mine",mine);p.put("customer",customer);p.put("opportunity",opportunity);p.put("q",text(q));p.put("limit",size);p.put("offset",((long)page-1)*size);
        String where=TASK_READ+" AND (:state='' OR x.status=:state OR (:state='OVERDUE' AND x.status='PENDING' AND x.due_date<cast(:today AS date))) AND (NOT :mine OR x.assignee_member_id=:member) AND (cast(:customer AS uuid) IS NULL OR x.customer_id=:customer) AND (cast(:opportunity AS uuid) IS NULL OR x.opportunity_id=:opportunity) AND (:q='' OR strpos(lower(x.title),lower(:q))>0)";
        long total=db.queryForObject("SELECT count(*)"+TASK_FROM+"WHERE "+where,p,Long.class);return new BusinessService.Page<>(rows(TASK_SELECT+"WHERE "+where+" ORDER BY CASE WHEN x.status='PENDING' THEN 0 ELSE 1 END,x.due_date,x.id LIMIT :limit OFFSET :offset",p),page,size,total);
    });}
    private void validateFilters(AuthService.Session s,AuthService.Actor a,UUID customer,UUID opportunity){if(customer!=null){if(!a.canReadCustomers())throw ApiError.forbidden("没有关联客户读取权限");customers.get(a,customer);}if(opportunity!=null){if(!a.businessAccess().opportunities().read())throw ApiError.forbidden("没有关联商机读取权限");var o=opportunity(a,opportunity);if(customer!=null&&!customer.equals(o.get("customerId")))throw ApiError.bad("商机与客户筛选不匹配");}}
    private void links(AuthService.Actor a,UUID customer,UUID opportunity){if(opportunity!=null&&customer==null)throw ApiError.bad("关联商机需要同时选择其客户");if(customer!=null)customerWrite(a,customer);if(opportunity!=null){if(!a.businessAccess().opportunities().read())throw ApiError.forbidden("没有关联商机读取权限");var o=opportunity(a,opportunity);if(!customer.equals(o.get("customerId")))throw ApiError.bad("商机不属于所选客户");opportunityWrite(a,opportunity,true);}}
    private Map<String,Object> taskParams(AuthService.Actor a,UUID id,String title,String description,UUID assignee,LocalDate due,String priority){date(due);owner(a,"task",assignee);var p=params(a);p.put("id",id);p.put("title",text(title));p.put("description",text(description));p.put("assignee",assignee);p.put("date",due);p.put("priority",priority);return p;}
    public Map<String,Object> createTask(AuthService.Session s,TaskCreate input,String key,UUID trace){return scoped(s,"task",true,a->{UUID id=once(a,"task.create",key,input,()->{links(a,input.customerId(),input.opportunityId());UUID created=UUID.randomUUID();var p=taskParams(a,created,input.title(),input.description(),input.assigneeMemberId(),input.dueDate(),input.priority());recipient(a,input.assigneeMemberId(),input.customerId(),input.opportunityId());p.put("customer",input.customerId());p.put("opportunity",input.opportunityId());db.update("INSERT INTO crm_task(id,tenant_id,customer_id,opportunity_id,title,description,assignee_member_id,created_by_member_id,due_date,priority) VALUES(:id,:tenant,:customer,:opportunity,:title,:description,:assignee,:member,:date,:priority)",p);audit(a,"TASK_CREATED","TASK",created,0,trace);return created;});return task(a,id);});}
    public Map<String,Object> editTask(AuthService.Session s,UUID id,TaskEdit input,UUID trace){return scoped(s,"task",true,a->{var current=task(a,id);if(!(boolean)current.get("canWrite"))throw ApiError.forbidden("无权编辑该待办");if(!"PENDING".equals(current.get("status")))throw ApiError.conflict("已完成的待办请先重新开启");recipient(a,input.assigneeMemberId(),(UUID)current.get("customerId"),(UUID)current.get("opportunityId"));var p=taskParams(a,id,input.title(),input.description(),input.assigneeMemberId(),input.dueDate(),input.priority());p.put("version",input.expectedVersion());int changed=db.update("UPDATE crm_task SET title=:title,description=:description,assignee_member_id=:assignee,due_date=:date,priority=:priority,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND version=:version AND status='PENDING'",p);if(changed!=1)throw ApiError.conflict("待办已变化，请刷新后保存");audit(a,"TASK_UPDATED","TASK",id,input.expectedVersion()+1,trace);return task(a,id);});}
    public Map<String,Object> taskState(AuthService.Session s,UUID id,VersionInput input,String key,boolean complete,UUID trace){return scoped(s,"task",true,a->{UUID selected=once(a,complete?"task.complete":"task.reopen",key,new TargetRequest(id,input),()->{var current=task(a,id);if(!(boolean)current.get("canWrite"))throw ApiError.forbidden("无权处理该待办");String from=complete?"PENDING":"DONE";if(!from.equals(current.get("status")))throw ApiError.conflict("待办状态已变化，请刷新");var p=params(a);p.put("id",id);p.put("version",input.expectedVersion());p.put("from",from);p.put("to",complete?"DONE":"PENDING");p.put("complete",complete);int changed=db.update("UPDATE crm_task SET status=:to,completed_at=CASE WHEN :complete THEN now() ELSE NULL END,version=version+1,updated_at=now() WHERE tenant_id=:tenant AND id=:id AND status=:from AND version=:version",p);if(changed!=1)throw ApiError.conflict("待办已变化，请刷新");audit(a,complete?"TASK_COMPLETED":"TASK_REOPENED","TASK",id,input.expectedVersion()+1,trace);return id;});return task(a,selected);});}
    static final String ACTIVITY_FROM=" FROM crm_activity x JOIN crm_customer c ON c.tenant_id=x.tenant_id AND c.id=x.customer_id LEFT JOIN crm_opportunity o ON o.tenant_id=x.tenant_id AND o.id=x.opportunity_id JOIN sys_tenant_member m ON m.tenant_id=x.tenant_id AND m.id=x.actor_member_id ";
    static final String ACTIVITY_READ="x.tenant_id=:tenant AND "+LINK_READ;
    private static final String ACTIVITY_SELECT="SELECT x.*,c.customer_name,o.title AS opportunity_title,m.display_name AS actor_name"+ACTIVITY_FROM;
    Map<String,Object> activity(AuthService.Actor a,UUID id){var p=params(a);p.put("id",id);return one(ACTIVITY_SELECT+"WHERE "+ACTIVITY_READ+" AND x.id=:id",p);}
    public Map<String,Object> activity(AuthService.Session s,UUID id){return scoped(s,"activity",false,a->activity(a,id));}
    public BusinessService.Page<Map<String,Object>> activities(AuthService.Session s,int page,int size,String q,UUID customer,UUID opportunity){page(page,size,q);return scoped(s,"activity",false,a->{validateFilters(s,a,customer,opportunity);var p=params(a);p.put("customer",customer);p.put("opportunity",opportunity);p.put("q",text(q));p.put("limit",size);p.put("offset",((long)page-1)*size);String where=ACTIVITY_READ+" AND (cast(:customer AS uuid) IS NULL OR x.customer_id=:customer) AND (cast(:opportunity AS uuid) IS NULL OR x.opportunity_id=:opportunity) AND (:q='' OR strpos(lower(x.content),lower(:q))>0 OR strpos(lower(c.customer_name),lower(:q))>0)";long total=db.queryForObject("SELECT count(*)"+ACTIVITY_FROM+"WHERE "+where,p,Long.class);return new BusinessService.Page<>(rows(ACTIVITY_SELECT+"WHERE "+where+" ORDER BY x.occurred_at DESC,x.id LIMIT :limit OFFSET :offset",p),page,size,total);});}
    public Map<String,Object> createActivity(AuthService.Session s,ActivityCreate input,String key,UUID trace){return scoped(s,"activity",true,a->{UUID id=once(a,"activity.create",key,input,()->{links(a,input.customerId(),input.opportunityId());if(input.occurredAt().isAfter(Instant.now().plusSeconds(300))||input.occurredAt().isBefore(Instant.parse("2000-01-01T00:00:00Z")))throw ApiError.bad("跟进时间无效，不能记录未来的沟通");UUID created=UUID.randomUUID();var p=params(a);p.put("id",created);p.put("customer",input.customerId());p.put("opportunity",input.opportunityId());p.put("type",input.activityType());p.put("content",text(input.content()));p.put("occurred",java.sql.Timestamp.from(input.occurredAt()));db.update("INSERT INTO crm_activity(id,tenant_id,customer_id,opportunity_id,activity_type,content,occurred_at,actor_member_id) VALUES(:id,:tenant,:customer,:opportunity,:type,:content,:occurred,:member)",p);audit(a,"ACTIVITY_CREATED","ACTIVITY",created,0,trace);return created;});return activity(a,id);});}
    public Map<String,Object> summary(AuthService.Session s){return scoped(s,"",false,a->{var p=params(a);var b=a.businessAccess();var result=new LinkedHashMap<String,Object>();
        result.put("customers",a.canReadCustomers()?db.queryForObject("SELECT count(*) FROM crm_customer c WHERE "+CustomerService.READ,p,Long.class):null);
        result.put("leads",b.leads().read()?business.leads(s,1,1,"","").total():null);
        result.put("openOpportunities",b.opportunities().read()&&a.canReadCustomers()?db.queryForObject("SELECT count(*)"+OP_FROM+"WHERE "+OP_READ+" AND o.stage NOT IN ('WON','LOST')",p,Long.class):null);
        p.put("today",LocalDate.now(ZoneId.of("Asia/Shanghai")));result.put("myPendingTasks",b.tasks().read()?db.queryForObject("SELECT count(*)"+TASK_FROM+"WHERE "+TASK_READ+" AND x.assignee_member_id=:member AND x.status='PENDING'",p,Long.class):null);
        result.put("myOverdueTasks",b.tasks().read()?db.queryForObject("SELECT count(*)"+TASK_FROM+"WHERE "+TASK_READ+" AND x.assignee_member_id=:member AND x.status='PENDING' AND x.due_date<cast(:today AS date)",p,Long.class):null);return result;
    });}
    private UUID once(AuthService.Actor a,String operation,String key,Object input,Supplier<UUID> fn){if(!key.matches("[A-Za-z0-9_.:-]{1,100}"))throw ApiError.bad("请求编号格式无效");String hash;try{hash=Crypto.hash(json.writeValueAsString(input));}catch(Exception e){throw new IllegalStateException(e);}var p=params(a);p.put("op",operation);p.put("key",key);p.put("hash",hash);db.update("INSERT INTO sys_idempotency_request(tenant_id,member_id,operation,request_key,request_hash) VALUES(:tenant,:member,:op,:key,:hash) ON CONFLICT DO NOTHING",p);var prior=db.queryForMap("SELECT request_hash,result_id FROM sys_idempotency_request WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key FOR UPDATE",p);if(!hash.equals(prior.get("request_hash")))throw ApiError.conflict("相同请求编号对应的内容已变化");if(prior.get("result_id")!=null)return (UUID)prior.get("result_id");UUID id=fn.get();p.put("id",id);db.update("UPDATE sys_idempotency_request SET result_id=:id WHERE tenant_id=:tenant AND member_id=:member AND operation=:op AND request_key=:key",p);return id;}
    private void audit(AuthService.Actor a,String action,String type,UUID id,long version,UUID trace){db.update("INSERT INTO sys_audit_log(id,tenant_id,actor_member_id,action,entity_type,entity_id,business_version,trace_id) VALUES(:id,:tenant,:member,:action,:type,:entity,:version,:trace)",Map.of("id",UUID.randomUUID(),"tenant",a.tenant().id(),"member",a.tenant().memberId(),"action",action,"type",type,"entity",id,"version",version,"trace",trace));}
}
